import json
import math
from pathlib import Path
import statistics

root = Path(__file__).resolve().parent
summary = {}
for kind in ['throughput', 'software-throughput', 'latency']:
    path = root / f'{kind}-metadata.json'
    if not path.exists():
        continue
    meta = json.loads(path.read_text())
    grouped = {}
    for run in meta['runs']:
        data = json.loads((root / run['file']).read_text())
        for sample in data.get('throughput', data.get('latency', [])):
            workload = sample.get('workload', sample.get('condition'))
            grouped.setdefault(workload, {}).setdefault(run['name'], []).append(sample)
    aggregate = {}
    for workload, builds in grouped.items():
        aggregate[workload] = {}
        for name, samples in builds.items():
            if 'seconds' in samples[0]:
                values = [s['seconds'] for s in samples]
                aggregate[workload][name] = dict(
                    median_seconds=statistics.median(values),
                    min_seconds=min(values), max_seconds=max(values),
                    median_mib_s=statistics.median([s['bytes'] / s['seconds'] / 1048576 for s in samples]),
                    trials=len(samples), bytes_per_trial=samples[0]['bytes'])
            else:
                values = sorted(v for sample in samples for v in sample['milliseconds'])
                total = sorted(v for sample in samples for v in sample['request_milliseconds'])
                p99 = lambda seq: seq[math.ceil(len(seq) * .99) - 1]
                aggregate[workload][name] = dict(
                    median_ms=statistics.median(values), p99_ms=p99(values),
                    request_p99_ms=p99(total), samples=len(values),
                    achieved_mib_s=[s['achieved_mib_s'] for s in samples])
    summary[kind] = aggregate
(root / 'summary.json').write_text(json.dumps(summary, indent=2) + '\n')
print(json.dumps(summary, indent=2))
